// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/customers", wrapper.ListCustomers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/customers/{customer_id}", wrapper.RetrieveCustomer)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/subscriptions", wrapper.ListSubscriptions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/subscriptions/{subscription_id}", wrapper.RetrieveSubscription)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v2/subscriptions/{subscription_id}/cancel_for_items", wrapper.CancelSubscriptionForItems)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/invoices", wrapper.ListInvoices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/invoices/{invoice_id}", wrapper.RetrieveInvoice)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/transactions", wrapper.ListTransactions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/transactions/{transaction_id}", wrapper.RetrieveTransaction)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/comments", wrapper.ListComments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v2/comments", wrapper.CreateComment)

	return m
}

